import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {
  loginForm: FormGroup;
  error = '';
  loading = false;

  constructor(private fb: FormBuilder, private auth: AuthService, private router: Router) {
    this.loginForm = this.fb.group({
      email: ['', [Validators.required, Validators.email]],
      password: ['', Validators.required]
    });
  }

  onSubmit(): void {
    if (this.loginForm.invalid) { this.loginForm.markAllAsTouched(); return; }
    this.loading = true;
    this.error = '';
    this.auth.login(this.loginForm.value).subscribe({
      next: () => this.router.navigate(['/']),
      error: () => { this.error = 'Invalid credentials.'; this.loading = false; }
    });
  }

  fillAdmin(): void { this.loginForm.setValue({ email: 'admin@shopez.com', password: 'admin123' }); }
  fillUser(): void { this.loginForm.setValue({ email: 'user@shopez.com', password: 'user123' }); }
}
<div class="auth-page">
  <div class="auth-card">
    <div class="auth-brand">🛍️ ShopEZ</div>
    <h2>Welcome Back</h2>
    <p class="auth-sub">Sign in to your account</p>

    <div class="demo-pills">
      <span>Quick fill:</span>
      <button (click)="fillAdmin()">Admin</button>
      <button (click)="fillUser()">Customer</button>
    </div>

    <form [formGroup]="loginForm" (ngSubmit)="onSubmit()">
      <div class="form-group">
        <label>Email</label>
        <input type="email" formControlName="email" placeholder="you@email.com" />
        <span class="err" *ngIf="loginForm.get('email')?.invalid && loginForm.get('email')?.touched">Valid email required.</span>
      </div>
      <div class="form-group">
        <label>Password</label>
        <input type="password" formControlName="password" placeholder="••••••••" />
        <span class="err" *ngIf="loginForm.get('password')?.invalid && loginForm.get('password')?.touched">Password required.</span>
      </div>
      <div class="err" *ngIf="error">{{ error }}</div>
      <button type="submit" class="auth-btn" [disabled]="loading">
        {{ loading ? 'Signing in...' : 'Sign In' }}
      </button>
    </form>

    <p class="auth-link">Don't have an account? <a routerLink="/register">Register</a></p>
  </div>
</div>
